import {displayNumber} from './number-display.js';
import {incrementalRecord} from './incremental-registry.js';
import {annualTextHTML as a} from './annual-localization.js';
import {cdnsStubCalculation} from './cdns-opening-stub.js';
const esc=x=>String(x??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const n=(value,digits=2)=>displayNumber(value,digits);
export const CDNS_STUB_NOTE='H2 2026 cash flows and its discount rate are fixed to the selected source case. Annual edits, simulations and horizon extensions affect FY2027 onward only; they do not reproduce source whole-curve WACC sensitivities.';
export const CDNS_CLAIM_NOTE='The residual allowance and award inventory are conditional assumptions, not verified complete liabilities or June award counts. February 19 awards are assumed unchanged at June 30; October 18 information is used. Listed stresses are examples, not bounds or probabilities. Blank means unknown.';
export function cdnsStubHTML(d,{id=false,detail=false}={}){
 if(!d?.openingStub)return '';const s=cdnsStubCalculation(d);
 return `<div class="annual-anchor cdns-opening-stub"${id?' id="cdns-stub-help"':''}><b>${a('Fixed opening half-year')} · H2 2026 · 2026-07-01–2026-12-31</b><p>${a(CDNS_STUB_NOTE)}</p><p>${a('Selected full-FY2026 forecast reference')}: ${n(d.anchor.revenue)} USDm · ${a('economic EBIT')}: ${n(d.anchor.EBIT)} USDm<br>${a('Fixed H2 FCFF')}: ${n(s.fcff)} USDm · WACC ${n(s.wacc*100)}% · t = 0.5 · PV ${n(s.pv)} USDm</p><p class="micro">${a('FY2027 is year 1 at t = 1.5. The annual tail ends at t = number of annual years + 0.5. H1 actual cash flows are not valued again. The FY2026 reference mixes reported H1 and normalized H2; it is not reported full-year actuals.')}</p>${detail?`<p>${a('H2 revenue / EBIT / operating tax / investment')}: ${[s.revenue,s.ebit,s.tax,s.reinvestment].map(n).join(' / ')} USDm<br>${a('Selected future-new-grant cost rate')}: ${n(s.futureNewGrantRate*100)}% · ${a('already retained in economic EBIT; legacy accounting reversal creates no uplift')}</p>`:''}</div>`;
}
export function cdnsAllocationHTML(b,{compact=false}={}){
 if(b?.claimAllocationModel!=='cdns-conditional-full-participation-v3'||!b.eligible)return '';
 if(compact)return `<p class="annual-summary-caveat incremental-cdns-claim-limits">${a('Residual claim allowance')}: ${n(b.inputs.residualClaimBudget)} USDm · ${a('adequacy unverified')}<br>${a('Allocation units')}: ${n(b.allocationUnits)}m · ${a('award inventory assumed, not reconciled')}<br>${a('Marketable-asset recovery')}: ${n(b.inputs.marketableRecovery*100)}% · ${a('conditional liquidity and tax assumption')}<br>${a('June 30 origin and cash/common shares; February 19 assumed award inventory; October 18 information. No current-price or as-known comparison.')}${b.unallocatedShortfall>0?`<br><b>${a('Signed pool deficit')}: ${n(b.unallocatedShortfall)} USDm</b>`:''}</p>`;
 return `<p class="annual-summary-caveat cdns-allocation-details">${a('Signed pool before assumed award participation')}: ${n(b.equityPoolBeforeExistingEquityClaims)} USDm<br>${a('Common-share allocation')}: ${n(b.equity)} USDm / ${n(b.basicShares)}m<br>${a('Assumed award allocation')}: ${n(b.assumedAwardEquity)} USDm / ${n(b.assumedAwardUnits)}m<br>${a('Total allocation units')}: ${b.allocationUnits.toLocaleString('en-US',{maximumFractionDigits:2})}m · ${a('Exercise proceeds')}: 0<br>${a('Options and ESPP use zero-price full participation, not option fair value. Signed source allocation and any deficit are retained. The residual allowance is deducted once; its reference components are not additional claims.')}</p><p>${a(CDNS_CLAIM_NOTE)}</p>`;
}
export function cdnsHistoryHTML(d,group){
 const r=incrementalRecord(d?.ticker);if(r?.bridge.type!=='cdns-v3')return '';
 const field=group==='growth'?'revenue':group==='profitability'?'operating_income':'capex';
 const labels=group==='growth'?['Fiscal year','Revenue · USDm','Reported revenue growth %']:group==='profitability'?['Fiscal year','Reported EBIT margin %','Reported SBC / revenue %','Reported tax / pretax income %']:['Fiscal year','Capex · USDm','CFO − capex − SBC · USDm'];
 const rows=r.history.map((h,i)=>{const v=h.normalizedValues,prev=r.history[i-1],values=group==='growth'?[h.revenue,prev?(h.revenue/prev.revenue-1)*100:null]:group==='profitability'?[h.operatingMargin*100,v.sbc/h.revenue*100,v.pretax_income>0?v.income_tax_expense/v.pretax_income*100:null]:[v.capex,v.fcf_after_sbc];return {h,values};});
 const values=rows.map(x=>x.values[group==='growth'?1:0]).filter(Number.isFinite),range=values.length?`${n(Math.min(...values))}–${n(Math.max(...values))}${group==='capital'?' USDm':'%'}`:'—';
 return `<div class="cdns-history-reference"><p class="micro"><b>${a('FY2016–2025 reported reference')}:</b> ${a(group==='growth'?'Revenue growth':group==='profitability'?'EBIT margin':'Capital expenditure')} ${range}. ${a('Historical observations, not forecast bounds.')}</p><details><summary>${a('Ten-year figures and sources')}</summary><div class="research-table-scroll"><table class="research-table"><caption>${a('Reported annual references; fiscal and acquisition comparability varies')}</caption><thead><tr>${labels.map(x=>`<th>${a(x)}</th>`).join('')}</tr></thead><tbody>${rows.map(({h,values})=>`<tr><th><a href="${esc(h.provenance[field]?.url||r.identity.reportPath+'#history')}" target="_blank" rel="noopener">${h.fiscalYear} ↗</a></th>${values.map(x=>`<td>${n(x)}</td>`).join('')}</tr>`).join('')}</tbody></table></div><p class="micro">${a(group==='capital'?'CFO − capex − SBC is a historical cash proxy, not FCFF or a sales-to-capital estimate. Forward investment includes an analyst incremental-NOPAT funding budget. Historical WACC is not inferred.':'Reported margins retain SBC, R&D and acquired amortization. Acquisition mix, revenue recognition, tax benefits and fiscal calendars limit comparisons with normalized forecasts.')}</p></details></div>`;
}
